// Package agent performs the few operations that need the LXD host itself
// rather than the LXD API: setting the desktop password inside a container,
// preparing a subscriber's persistent home directory with the container's
// isolated UID mapping, reading logs and sampling NVIDIA GPU telemetry.
//
// It is enabled only when Type3 runs on the LXD host (TYPE3_LOCAL_AGENT=true).
// Every argument passed to a command is validated or generated by Type3.
package agent

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/Heraldic-Clouds/Type3-hypervisor-manager/internal/gpu"
)

// Runner runs a command with optional stdin and returns stdout.
type Runner func(ctx context.Context, stdin []byte, name string, args ...string) ([]byte, error)

// Exec is the real Runner.
func Exec(ctx context.Context, stdin []byte, name string, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, name, args...)
	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		msg := strings.TrimSpace(errb.String())
		if len(msg) > 300 {
			msg = msg[:300]
		}
		return out.Bytes(), fmt.Errorf("%s %s: %w: %s", name, firstArg(args), err, msg)
	}
	return out.Bytes(), nil
}
func firstArg(a []string) string {
	if len(a) == 0 {
		return ""
	}
	return a[0]
}

// Agent is the host-local helper.
type Agent struct {
	Run Runner
	// HomeRoot is the host directory (an EFS mount) holding one directory per
	// subscriber. Empty disables persistent homes.
	HomeRoot string
	// GuestUID is the UID of the customer account inside containers.
	GuestUID int
	MkdirAll func(string, os.FileMode) error
	Chown    func(string, int, int) error
	Chmod    func(string, os.FileMode) error
	Stat     func(string) (os.FileInfo, error)
}

func New(homeRoot string) *Agent {
	return &Agent{Run: Exec, HomeRoot: homeRoot, GuestUID: 1000, MkdirAll: os.MkdirAll, Chown: os.Chown, Chmod: os.Chmod, Stat: os.Stat}
}

var safe = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)
var owner = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$`)

// SetPassword sets the customer account password inside a running container
// through chpasswd on stdin, so the password never appears in a process list.
func (a *Agent) SetPassword(ctx context.Context, container, user, password string) error {
	if !safe.MatchString(container) || !safe.MatchString(user) {
		return errors.New("invalid container or user name")
	}
	if len(password) < 16 || len(password) > 128 || strings.ContainsAny(password, ":\n\r") {
		return errors.New("password must be 16-128 characters without ':' or newlines")
	}
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	// Wait for cloud-init to create the account on first boot.
	if _, err := a.Run(ctx, nil, "lxc", "exec", container, "--", "cloud-init", "status", "--wait"); err != nil {
		// cloud-init exits 2 for "done with recoverable errors"; the id check below decides.
		_ = err
	}
	if _, err := a.Run(ctx, nil, "lxc", "exec", container, "--", "id", "-u", user); err != nil {
		return fmt.Errorf("account %s is not ready in %s", user, container)
	}
	_, err := a.Run(ctx, []byte(user+":"+password+"\n"), "lxc", "exec", container, "--", "chpasswd")
	return err
}

// HomePath returns the host path of a subscriber's persistent directory.
func (a *Agent) HomePath(ownerID string) (string, error) {
	if a.HomeRoot == "" {
		return "", errors.New("persistent home storage is not configured")
	}
	if !owner.MatchString(ownerID) || strings.Contains(ownerID, "..") {
		return "", errors.New("invalid owner id")
	}
	return filepath.Join(a.HomeRoot, ownerID), nil
}

// PrepareHome creates the subscriber directory (mode 0700) owned by the
// host UID that the container's isolated idmap assigns to the guest user.
// Another subscriber's container maps to a different host UID range and only
// ever has its own directory mounted, so it cannot read this one.
func (a *Agent) PrepareHome(ctx context.Context, container, ownerID string) (string, error) {
	path, err := a.HomePath(ownerID)
	if err != nil {
		return "", err
	}
	if !safe.MatchString(container) {
		return "", errors.New("invalid container name")
	}
	out, err := a.Run(ctx, nil, "lxc", "config", "get", container, "volatile.idmap.base")
	if err != nil {
		return "", err
	}
	base, err := strconv.Atoi(strings.TrimSpace(string(out)))
	if err != nil || base <= 0 {
		return "", fmt.Errorf("container %s has no isolated idmap yet (start it first)", container)
	}
	if err = a.MkdirAll(path, 0o700); err != nil {
		return "", err
	}
	uid := base + a.GuestUID
	if err = a.Chown(path, uid, uid); err != nil {
		return "", err
	}
	return path, a.Chmod(path, 0o700)
}

// Usage returns bytes used under a subscriber directory.
func (a *Agent) Usage(ctx context.Context, ownerID string) (int64, error) {
	path, err := a.HomePath(ownerID)
	if err != nil {
		return 0, err
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	out, err := a.Run(ctx, nil, "du", "-sb", "--", path)
	if err != nil {
		return 0, err
	}
	f := strings.Fields(string(out))
	if len(f) == 0 {
		return 0, errors.New("du returned nothing")
	}
	return strconv.ParseInt(f[0], 10, 64)
}

// Logs returns the LXD instance log and the container's recent XRDP journal.
func (a *Agent) Logs(ctx context.Context, container string, lines int) (string, error) {
	if !safe.MatchString(container) {
		return "", errors.New("invalid container name")
	}
	if lines <= 0 || lines > 1000 {
		lines = 200
	}
	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	info, err := a.Run(ctx, nil, "lxc", "info", container, "--show-log")
	if err != nil {
		return "", err
	}
	journal, jerr := a.Run(ctx, nil, "lxc", "exec", container, "--", "journalctl", "--no-pager", "-n", strconv.Itoa(lines), "-u", "xrdp", "-u", "xrdp-sesman")
	s := string(info)
	if jerr == nil {
		s += "\n--- xrdp journal ---\n" + string(journal)
	}
	return s, nil
}

// GPUs samples every NVIDIA GPU with nvidia-smi, including NVENC load.
func (a *Agent) GPUs(ctx context.Context) ([]gpu.Utilization, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	out, err := a.Run(ctx, nil, "nvidia-smi", "--query-gpu=uuid,utilization.gpu,memory.used,memory.total,utilization.encoder,utilization.decoder,encoder.stats.sessionCount", "--format=csv,noheader,nounits")
	if err != nil {
		return nil, err
	}
	return ParseSMI(string(out))
}

// ParseSMI parses nvidia-smi CSV. Unsupported fields ("[N/A]") read as zero.
func ParseSMI(s string) ([]gpu.Utilization, error) {
	res := []gpu.Utilization{}
	for _, line := range strings.Split(strings.TrimSpace(s), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		f := strings.Split(line, ",")
		if len(f) < 7 {
			return nil, fmt.Errorf("unexpected nvidia-smi output")
		}
		num := func(i int) float64 {
			v, err := strconv.ParseFloat(strings.TrimSpace(f[i]), 64)
			if err != nil {
				return 0
			}
			return v
		}
		res = append(res, gpu.Utilization{
			UUID: strings.TrimSpace(f[0]), GPUPercent: num(1),
			MemoryUsedBytes: uint64(num(2)) << 20, MemoryTotalBytes: uint64(num(3)) << 20,
			EncoderPercent: num(4), DecoderPercent: num(5), EncoderSessions: int(num(6)),
		})
	}
	return res, nil
}
